    choiRole: "לב שנרפא מבושה",
    hanName: "Han Ye-seul",
    hanRole: "ממאמץ למנוחה בשירות",
    keziahRole: "מפגש עם אהבת האב",
    parichatRole: "חופש מכאב ארוך שנים",
    jiName: "Ji Yeowoon",
    jiRole: "New Heart Kids #2 — קוריאה",
